def h(t): parts.append('<h2>'+t+'</h2>')
def table(headers, rows):
 parts.append('<table><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</table>')
def page():parts.append('<div style="page-break-before:always"></div>')
parts.append('<h1>More than a Hack 2027</h1><p class="subtitle">Análisis del proyecto, primera fase y archivos compartidos</p><p>20 de octubre de 2026</p>')
p('<b>Objetivo inmediato:</b> desarrollar un algoritmo que indique, para cada fotograma de un partido, si tiene la posesión el Barcelona, el Athletic o si el balón está fuera de juego. Entrega: <b>17 de noviembre de 2026</b>.')
p('Alcance: revisión de los 10 archivos de C:/Users/ruben/OneDrive/Escritorio/MoreThanAHack y contraste con la documentación oficial. En los vídeos se inspeccionaron metadatos del contenedor; no se realizó un visionado completo. Los resultados de inspección local se distinguen de las recomendaciones de implementación.')
h('1. Convocatoria y calendario')
p('El enlace inicial de Talent Arena conserva información de la edición 2026: Football GPT Bootcamp, fechas anteriores y reto abierto de IA generativa. Para esta fase deben utilizarse la convocatoria 2027 y el repositorio oficial. [1, 2, 3]')
table(['Etapa','Fechas','Objetivo'],[
['Inscripción','1 octubre - 10 noviembre 2026','Registro de participantes y equipos'],['Initial Challenge','20 octubre - 17 noviembre 2026','Estimar posesión en cada fotograma'],['Innovation Challenge','26 noviembre 2026 - 14 enero 2027','Los 20 mejores desarrollan propuestas analíticas o tácticas'],['Final Pitch','2 marzo 2027','Los 5 finalistas presentan en Talent Arena']])
p('Organizan Mobile World Capital Barcelona, Barça Innovation Hub y Metrica Sports. La segunda fase ofrece 10 partidos profesionales y mentoría. Para acceder a ella y a la final, el equipo debe tener entre 3 y 5 miembros. Ahora conviene concentrarse en el reto de posesión; la propuesta abierta de producto o análisis corresponde a la siguiente etapa. [2]')
h('2. Qué hay que resolver')
p('El partido es FC Barcelona-Athletic Club, jornada 2 de LaLiga 2024-25. Cada fila de la entrega corresponde a un fotograma del vídeo táctico. [4, 5]')
table(['Etiqueta','Significado'],[['H','Barcelona, equipo local, con posesión y balón en juego'],['A','Athletic, equipo visitante, con posesión y balón en juego'],['D','Balón fuera de juego: interrupción o parada'],['X','El sistema se abstiene de responder']])
p('La posesión implica control, no mera proximidad. En un balón dividido se mantiene el último poseedor hasta que el rival obtiene control. Un rebote, desvío aislado o duelo aéreo sin control posterior no implica necesariamente cambio. No existe una clase real de "disputa": durante el juego siempre se asigna un equipo. Un tramo H-H-D-D-H-H contiene dos posesiones separadas por una interrupción. [4]')
page()
h('3. Entregables y evaluación')
table(['Entregable','Requisitos'],[['CSV de posesión','Cabecera frame,label; 199.319 filas de datos; índices 0 a 199318, consecutivos; etiquetas H/A/D/X; sin celdas vacías ni columna de índice adicional. UTF-8.'],['Repositorio público','Código, dependencias fijadas, instalación y comando que regeneren exactamente el CSV. No incluir los datos restringidos.'],['Memoria técnica','PDF o Markdown de pocas páginas: método, fuentes utilizadas o descartadas, reglas de posesión, limitaciones y reproducción.']])
p('Los tres entregables se envían mediante un formulario que la organización comunica por correo. Un CSV inválido queda fuera de la evaluación. Debe comprobarse antes de enviarlo: <b>python evaluation/validate_submission.py my_submission.csv</b>. [7]')
p('<b>spellF1 determina la clasificación.</b> Evalúa las posesiones como intervalos completos. Empareja predicciones y posesiones reales mediante solapamiento temporal (IoU), y promedia F1 para umbrales 0,3; 0,4; 0,5; 0,6 y 0,7. Los intervalos D son interrupciones, no posesiones. [6]')
p('<b>macroF1</b> evalúa las etiquetas por fotograma, promediando F1 de H, A y D; es el primer desempate. Acertar muchos fotogramas no garantiza un buen spellF1: cambios espurios fragmentan una posesión real en muchas predicciones. [6]')
p('El repositorio ofrece cuatro baselines, evaluador y etiquetas de referencia de los primeros cinco minutos de juego. El baseline publicado a superar alcanza <b>spellF1 = 0,2433</b>. La clasificación se calcula con la referencia privada del partido completo. [3]')
p('La ventana pública sirve para comprobar el sistema, pero no garantiza generalización: la configuración que gana en esos cinco minutos puede perder en el partido completo. Evitar ajustar todos los parámetros exclusivamente a esa ventana. [9]')
p('X fuera de las ventanas evaluadas no penaliza. Dentro de ellas cuenta como error para macroF1; para spellF1 el evaluador prolonga la última etiqueta emitida en esa parte. Puede cubrir un hueco dentro de una posesión, pero retrasar un cambio real. [4, 6]')
h('4. Inventario completo de archivos')
p('Tamaños aproximados, en unidades decimales. El conjunto ocupa unos 19,56 GB. Se recibieron cinco archivos tácticos, cuatro de retransmisión y un README.')
table(['Archivo (carpeta)','Tamaño','Función'],[['README.md','2,2 KB','Organización y uso de los datos'],['BAR-ATH_tactical-001.mp4 (tactical)','5,22 GB','Vídeo de referencia'],['BAR-ATH_tactical_atd.xml (tactical)','59 KB','Metadatos del tracking'],['BAR-ATH_tactical_atd.txt (tactical)','195,71 MB','Tracking por fotograma'],['BAR-ATH_tactical_homography.csv (tactical)','23,19 MB','Geometría campo-imagen'],['BAR-ATH_tactical_smart_tagging.xml (tactical)','261 KB','Fases y acciones automáticas'],['BAR-ATH_broadcast-001.mp4 (broadcast)','13,96 GB','Retransmisión complementaria'],['BAR-ATH_broadcast_atd.xml (broadcast)','65 KB','Metadatos del tracking'],['BAR-ATH_broadcast_atd.txt (broadcast)','141,97 MB','Tracking de retransmisión'],['BAR-ATH_broadcast_homography.csv (broadcast)','15,40 MB','Geometría de retransmisión']])
page()
h('5. Análisis de README y vídeos')
p('<b>README.md.</b> Es el documento de la carpeta de datos, no la especificación completa. Remite a games.py, DATA.md y evaluation/run_evaluation.py, ausentes en la carpeta recibida. Tenéis el paquete de datos, pero falta incorporar el entorno oficial de desarrollo y evaluación. El README explica MTAH_DATA_DIR para indicar otra ubicación y recuerda que el material no debe subirse al repositorio público.')
table(['Metadato inspeccionado','Tactical','Broadcast'],[['Resolución','1920 × 1080','1920 × 1080'],['Duración del contenedor','2 h 12 min 52,76 s','1 h 49 min 39,52 s'],['Muestras de vídeo declaradas','199.319','164.487']])
p('<b>Tactical es la referencia.</b> La retransmisión no está sincronizada: contiene cortes y repeticiones y no se proporciona una tabla de correspondencia. No se pueden unir ambas fuentes por número de fotograma ni asumir un único desplazamiento constante. [5]')
p('<b>Incidencia a verificar:</b> el MP4 broadcast declara 164.487 muestras de vídeo, mientras que su tracking y homografía contienen 164.488 registros. Esto no demuestra que esté dañado; exige comprobar la correspondencia con un decodificador antes de utilizarlo.')
p('Recomendación: comenzar con tactical. Incorporar broadcast solo cuando resuelva errores concretos y se haya desarrollado su alineación temporal.')
h('6. XML y TXT de tracking')
p('<b>Los XML</b> describen proveedor, frecuencia, equipos, dimensiones y canales de datos. Se confirmó frecuencia de 25 Hz, campo declarado de 105 × 68 m, 46 slots en tactical y 51 en broadcast. Los equipos son Barcelona y Athletic.')
p('Track 1, Track 2 y sus números son identificadores del tracking, no futbolistas ni dorsales auténticos. Puede haber fragmentaciones, duplicados y cambios de identidad. Estos XML interpretan los TXT; no proporcionan las etiquetas finales de posesión. [5]')
p('<b>Los TXT</b> contienen las observaciones por fotograma. Se recorrieron completos para contar registros y comprobar si existían ambas coordenadas del balón:')
table(['Comprobación','Tactical','Broadcast'],[['Registros','199.319','164.488'],['Índices','1 a 199.319','1 a 164.488'],['Registros con balón x e y','113.488','83.121'],['Disponibilidad del balón','56,94 %','50,53 %']])
p('Los datos ausentes aparecen como NaN. La ausencia del balón no equivale a D: puede seguir en juego, oculto o fuera del encuadre. La documentación sitúa su ausencia en torno al 41 % de los fotogramas evaluados. [4]')
p('Las posiciones están normalizadas. Las distancias deben calcularse tras escalar los ejes por las dimensiones del campo. Asignar la posesión al jugador más cercano sirve de punto de partida, pero confunde pases, rebotes y disputas. El sistema debe conservar contexto temporal.')
page()
h('7. Homografía y Smart Tagging')
p('<b>Homografías.</b> Cada fila incluye nueve coeficientes de una matriz 3 × 3, error de reproyección y bandera valid. La matriz relaciona coordenadas normalizadas del campo con píxeles. Sirve para superponer tracking, revisar errores o integrar detecciones visuales. [5]')
table(['Comprobación local','Tactical','Broadcast'],[['Filas','199.319','164.488'],['Matrices marcadas válidas','199.319','108.248'],['Porcentaje válido','100 %','65,81 %']])
p('valid=1 indica que existe transformación; no garantiza precisión perfecta. El error de reproyección permite valorar la calidad. En broadcast hay muchas imágenes sin transformación útil por cambios de plano. [5]')
p('<b>Smart Tagging.</b> Se verificaron 638 instancias de fases y acciones:')
table(['Anotación','Cantidad','Anotación','Cantidad'],[['Jugadores en el área','97','Creación de ocasiones','30'],['Balón en último tercio','93','Defensa en tercio defensivo','30'],['Balón en el área','72','Balones largos','29'],['Progresión','66','Transición ofensiva','24'],['Defensa en tercio medio','66','Transición defensiva','24'],['Balón parado','59','Construcción de juego','22'],['Defensa en tercio ofensivo','22','Goles','4']])
p('Las 59 acciones a balón parado se distribuyen en 26 saques de banda, 12 córners, 10 saques de puerta, 5 faltas y 6 saques de centro. Hay 36 instancias con equipo N/A. Las etiquetas Team identifican 314 instancias de Barcelona y 288 de Athletic.')
p('Es contexto útil, no una solución resuelta. Las fases pueden solaparse o no coincidir con posesiones completas; las etiquetas son automáticas y contienen errores. Un tramo defensivo se refiere al equipo que defiende: no debe convertirse directamente en posesión de ese equipo. [5]')
page()
h('8. Alineación y errores de integración')
table(['Fuente','Conversión a fotograma de salida'],[['Tracking ATD','frame_salida = frame_id - 1'],['Homografía táctica','La columna frame ya coincide con la salida'],['Smart Tagging','frame_salida = round(segundos × 25)']])
p('Los tiempos de Smart Tagging se cuentan desde el inicio del vídeo táctico, no desde el minuto cero de juego. La entrega contiene todas las filas, aunque se evalúan 158.857 fotogramas. [5]')
table(['Tramo del vídeo táctico','Fotogramas (inclusive)','Evaluado'],[['Antes del partido','0 - 11184','No'],['Primera parte','11185 - 90651','Sí'],['Descanso','90652 - 110807','No'],['Segunda parte','110808 - 190197','Sí'],['Después del partido','190198 - 199318','No']])
p('Atención: los fotogramas 110808 a 113741 se evalúan y son D; el saque inicial de la segunda parte llega después. No confundirlos con descanso ignorado. [9]')
p('Los MP4 recibidos terminan en -001.mp4, mientras que los ejemplos usan nombres sin ese sufijo. Comprobar las rutas que construye games.py antes de ejecutar los notebooks. No cambiar de cronología al integrar broadcast.')
h('9. Propuesta de implementación')
p('Los pasos siguientes son recomendaciones técnicas, no requisitos adicionales de la organización.')
for t in [
'1. Cargar tactical y verificar índices, pertenencia de tracks a equipos, coordenadas y ausencias.',
'2. Reproducir los baselines oficiales y obtener un CSV válido antes de desarrollar mejoras.',
'3. Estimar evidencia por fotograma: distancia del balón a cada equipo, movimiento y contexto de Smart Tagging.',
'4. Modelar continuidad temporal: mantener posesión durante pases y oclusiones, y exigir evidencia de control rival para cambiar.',
'5. Detectar interrupciones por separado, combinando señales para distinguir balón parado de balón no observado.',
'6. Evaluar intervalos completos: fragmentaciones, cambios tardíos, falsas interrupciones y reinicios, además de macroF1.'
]:p(t)
p('Un modelo de estados, por ejemplo HMM o segmentación con duraciones, es una opción razonable para experimentar. Conviene comparar cada fuente añadida frente al mismo sistema sin ella para medir si aporta mejora. El vídeo completo no tiene que procesarse desde el primer día.')
page()
h('10. Plan de trabajo hasta la entrega')
table(['Periodo propuesto','Resultado esperado'],[['20 - 26 octubre','Entorno oficial, datos alineados y primer CSV válido'],['27 octubre - 2 noviembre','Continuidad de posesión y detección de interrupciones'],['3 - 9 noviembre','Comparación de variantes y errores en distintos tramos'],['10 - 16 noviembre','Congelar método, verificar reproducción y terminar memoria'],['17 noviembre','Entrega con margen']])
p('La prioridad inmediata es incorporar el repositorio oficial y reproducir sus baselines. Los comandos centrales, disponibles al añadirlo, son:')
